const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const registry = require('../events/registry.json');

const src = path.join(__dirname, '..', 'src');
const calls = fs.readdirSync(src, { recursive: true }).filter((f) => f.endsWith('.js'))
  .flatMap((f) => [...fs.readFileSync(path.join(src, f), 'utf8').matchAll(/track\('(\w+)'/g)].map((m) => m[1]));

test('every tracked event is registered and named object_action', () => {
  assert.ok(calls.length > 0);
  for (const name of calls) {
    assert.ok(registry[name], name + ' is not in events/registry.json');
    assert.match(name, /^[a-z]+(_[a-z]+)+$/);
  }
});
